"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { CopyHelper } from "theme/components/CopyHelper";
import { Flex, Text, styled as uiStyled, useSporeColors } from "ui/src";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { NumberType, useFormatter } from "utils/formatNumbers";
const ItemWrapper = uiStyled(Flex, {
  borderWidth: 1,
  borderColor: "$surface2",
  borderRadius: "$spacing12",
  flexDirection: "column",
  gap: "$gap4",
  width: "100%",
  padding: "$spacing12"
});
const HeaderRow = uiStyled(Flex, {
  flexDirection: "row",
  alignItems: "center",
  gap: "$gap12",
  marginBottom: "$spacing12"
});
const HeadingText = uiStyled(Text, {
  variant: "heading1",
  color: "$neutral1",
  $lg: {
    variant: "heading2"
  },
  $md: {
    variant: "heading3"
  }
});
const Badge = ({ icon, text }) => <Flex flexDirection="row" alignItems="center" gap="$gap4">
    {icon}
    <Text variant="body2" color="$neutral2">
      {text}
    </Text>
  </Flex>;
const StatsGrid = uiStyled(Flex, {
  marginTop: "$spacing24",
  "$platform-web": {
    display: "grid",
    gridTemplateColumns: "repeat(4, 1fr)",
    gap: "$gap12"
  },
  $xl: {
    gridTemplateColumns: "repeat(2, 1fr)"
  },
  $lg: {
    gridTemplateColumns: "repeat(1, 1fr)"
  }
});
const LabelText = uiStyled(Text, {
  variant: "body2",
  color: "$neutral2",
  marginBottom: "$spacing8"
});
const SubValueText = uiStyled(Text, {
  variant: "body4",
  color: "$neutral2",
  marginTop: "$spacing4"
});
const ValueText = uiStyled(Text, {
  variant: "heading3",
  color: "$neutral1"
});
const StatItem = ({
  label,
  value,
  subValue,
  icon
}) => <ItemWrapper>
    <LabelText>{label}</LabelText>
    <Flex flexDirection="row" alignItems="center" gap="$gap4">
      <ValueText>{value}</ValueText>
      {icon}
    </Flex>
    {subValue && <SubValueText>{subValue}</SubValueText>}
  </ItemWrapper>;
export default function Vault({ vaultData }) {
  const colors = useSporeColors();
  const { formatFiatPrice, formatNumber } = useFormatter();
  const chainId = UniverseChainId.Mainnet;
  return <Flex marginBottom={"$spacing12"}>
      {
    /* Title Section */
  }
      <CopyHelper iconPosition="right" visibleIcon={true} toCopy={vaultData.address}>
        <HeaderRow>
          <HeadingText>{vaultData.name}</HeadingText>
        </HeaderRow>
      </CopyHelper>

      {
    /* Badges */
  }
      <Flex flexDirection="row" gap="$gap16" marginBottom="$spacing24">
        <Badge
    icon={<PortfolioLogo
      chainId={chainId}
      tokenSymbol={vaultData.token.symbol}
      tokenName={vaultData.token.name}
      images={[getTokenLogoUrl(vaultData.token.address)]}
      size={18}
    />}
    text={vaultData.token.symbol}
  />
        <Badge text={vaultData.symbol} />
      </Flex>

      {
    /* Stats Grid */
  }
      <StatsGrid>
        <StatItem
    label="Total Deposits"
    value={formatFiatPrice({ price: vaultData.deposits, type: NumberType.FiatTokenStats })}
    subValue={`${formatNumber({ input: vaultData.deposits, type: NumberType.TokenTx })} ${vaultData.token.symbol}`}
  />
        <StatItem
    label="Liquidity"
    value={formatFiatPrice({ price: vaultData.liquidity, type: NumberType.FiatTokenStats })}
    subValue={`${formatNumber({ input: vaultData.liquidity, type: NumberType.TokenTx })} ${vaultData.token.symbol}`}
  />
        <StatItem label="Fee" value={`${vaultData.feePercent.toFixed(1)}%`} />
        <StatItem
    label="Share Price"
    value={`${vaultData.sharePrice.toFixed(vaultData.token.decimals <= 6 ? 4 : 8)} ${vaultData.token.symbol}`}
  />
      </StatsGrid>
    </Flex>;
}
